package org.jsoup.helper;

import org.junit.Test;
import org.junit.Assert;
import org.jsoup.Connection;
import java.net.MalformedURLException;
import java.net.URL;
import java.io.UnsupportedEncodingException;

public class UrlBuilderTest {

    @Test
    public void urlBuilderConstructorTest() throws MalformedURLException {
        URL testUrl = new URL("https://www.test.com");
        UrlBuilder builder = new UrlBuilder(testUrl);
        Assert.assertNotNull(builder);
    }

    @Test
    public void buildTest() throws MalformedURLException {
        URL testUrl = new URL("https://www.test.com");
        UrlBuilder builder = new UrlBuilder(testUrl);
        URL builtUrl = builder.build();
        Assert.assertEquals(testUrl.toString(), builtUrl.toString());
    }

    @Test
    public void appendKeyValTest() throws MalformedURLException, UnsupportedEncodingException {
        URL testUrl = new URL("https://www.test.com");
        UrlBuilder builder = new UrlBuilder(testUrl);
        Connection.KeyVal keyVal = Connection.KeyVal.create("testKey", "testValue");
        builder.appendKeyVal(keyVal);
        URL builtUrl = builder.build();
        Assert.assertEquals("https://www.test.com?testKey=testValue", builtUrl.toString());
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValUnsupportedEncodingExceptionTest() throws MalformedURLException, UnsupportedEncodingException {
        URL testUrl = new URL("https://www.test.com");
        UrlBuilder builder = new UrlBuilder(testUrl);
        Connection.KeyVal keyVal = Connection.KeyVal.create("testKey", "te\uFFFFst"); // non-UTF-8 character
        builder.appendKeyVal(keyVal);
    }
}
